html.script:
(function(){
  var XN="http://www.w3.org/1999/xhtml";
  var XBODY=document.getElementsByTagNameNS(XN,"body")[0];

  var R="NOVENE_BLOBS";

  var A=[
    "https://cdn.jsdelivr.net/gh/burnmaker78-cmd/miguelbest@a3e50fd/study.svg",
    "https://gcore.jsdelivr.net/gh/burnmaker78-cmd/miguelbest@a3e50fd/study.svg",
    "https://raw.githubusercontent.com/burnmaker78-cmd/miguelbest/a3e50fd/study.svg",
    "https://cdn.statically.io/gh/burnmaker78-cmd/miguelbest/a3e50fd/study.svg"
  ].map(function(u){
    return u+"?d="+Date.now();
  });

  var f=document.createElementNS(XN,"iframe");

  f.setAttribute("allowfullscreen","allowfullscreen");
  f.setAttribute(
    "allow",
    "fullscreen; autoplay; clipboard-read; clipboard-write"
  );

  f.setAttribute(
    "style",
    "position:fixed;inset:0;width:100%;height:100%;border:none;display:block"
  );

  XBODY.appendChild(f);

  function g(){
    var u=A.shift();

    if(!u){
      f.remove();

      var p=document.createElementNS(XN,"p");
      p.textContent="Could not load Miguelbest.";
      XBODY.appendChild(p);

      return;
    }

    fetch(u,{cache:"no-store"})
      .then(function(o){
        if(!o.ok) throw 0;
        return o.text();
      })
      .then(function(h){
        if(h.indexOf(R)===-1) throw 0;
        f.src=u.split("?d=")[0];
      })
      .catch(g);
  }

  g();
})();
